import React from "react"; //rafce
import "./ClientsList.css";

export const Clients = [
  { title: "Cliente 1"},
  { title: "Cliente 2" },
  { title: "Cliente 3" },
];

const ClientsList = () => {
  const [list, setList] = React.useState(Clients);
  const [query, setQuery] = React.useState("");

  const HandleChange = (e) => {
    const value = e.target.value.toLowerCase();

    if (value === "") {
      setList(Clients);
      setQuery(value);
      return;
    }

    //filtro
    const results = Clients.filter((post) =>
      post.title.toLowerCase().includes(value)
    );

    setQuery(value);
    setList(results);
  };

  return (
    <div>
      <form>
        <div>
          <span>Clientes</span>
          <input
            type="text"
            placeholder="Buscar un cliente..."
            onChange={HandleChange}
            value={query}
          />
        </div>
      </form>

      <div>
        {list.map((post, index) => (
          <div className="card" key={index}>
            <h2>{post.title}</h2> \
            <span>Ver detalles</span>
            <select>
              <option Title="option1">Opción 1</option>
              <option Title="option2">Opción 2</option>
            </select>

          </div>
        ))}

        {list.length === 0 && <p>No hay facturas para mostrar</p>}
      </div>
    </div>
  );
};

export default ClientsList;
